import sys
from collections import deque

def find_centroids(n, edges):
    graph = [[] for _ in range(n)]
    degree = [0] * n
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
        degree[u-1] += 1
        degree[v-1] += 1

    leaves = deque([i for i in range(n) if degree[i] == 1])
    while leaves:
        leaf = leaves.popleft()
        for neighbor in graph[leaf]:
            degree[neighbor] -= 1
            if degree[neighbor] == 1:
                leaves.append(neighbor)

    centroids = [i for i in range(n) if degree[i] > 1]
    if len(centroids) == 0:
        centroids = [0]

    return centroids

def can_be_made_centroid(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append((v-1, len(graph[u-1])))
        graph[v-1].append((u-1, len(graph[v-1])))

    def dfs(root, parent):
        subtree_size[root] = 1
        for neighbor, _ in graph[root]:
            if neighbor != parent:
                dfs(neighbor, root)
                subtree_size[root] += subtree_size[neighbor]

    subtree_size = [0] * n
    dfs(0, -1)

    def check_vertex(v):
        max_component = 0
        for neighbor, _ in graph[v]:
            if subtree_size[neighbor] > max_component:
                max_component = subtree_size[neighbor]
        if n - subtree_size[v] > max_component:
            max_component = n - subtree_size[v]
        return max_component <= (n + 1) // 2

    result = [0] * n
    for v in range(n):
        if check_vertex(v):
            result[v] = 1
            continue

        for neighbor, edge_index in graph[v]:
            original_size = subtree_size[neighbor]
            if subtree_size[v] > subtree_size[neighbor]:
                subtree_size[neighbor] = n - subtree_size[v]
            else:
                subtree_size[v] = n - subtree_size[neighbor]

            if check_vertex(v):
                result[v] = 1
                break

            subtree_size[neighbor] = original_size
            subtree_size[v] = n - subtree_size[neighbor]

    return result

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n-1)]
    result = can_be_made_centroid(n, edges)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
